    "apikey.howToGetTitle": "How to get a Gemini API key",
    "apikey.howToGet1": "You can get a free API key to access Gemini models in Google AI Studio.",
    "apikey.step1": "<li>Go to <a href=\"https://aistudio.google.com/app/apikey\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"underline text-[var(--accent-primary)] hover:text-[var(--accent-primary-hover)]\">Google AI Studio</a>.</li>",
    "apikey.step2": "<li>Sign in with your Google account.</li>",
    "apikey.step3": "<li>On the opened page, click the <strong>\"Create API key in new project\"</strong> button.</li>",
    "apikey.step4": "<li>After a few seconds, your key will be generated. It will look like a long string of random characters.</li>",
    "apikey.step5": "<li>Click the copy icon next to the key.</li>",
    "apikey.step6": "<li>Return here and paste the copied key into the field above.</li>",
    "apikey.warning2": "<strong>Important:</strong> Keep your key in a safe place and do not share it with anyone. The editor does not save the key permanently and does not transmit it anywhere except directly to the Google API when generating code.",
