    "about.title": "About \"VereTka\" editor",
    "about.p1": "<strong className=\"text-[var(--text-primary)]\">VereTkа</strong> is a simple vector editor designed for quick creation of graphic primitives and generating corresponding Python code for the Tkinter library.",
    "about.p2": "It uses a local code generator for instant and reliable results, and can also use the Google Gemini API for experimental capabilities.",
