    "apikey.warning1": "<strong>Importante:</strong> la tua chiave API verrà archiviata solo per la durata della sessione corrente e verrà eliminata dopo l’aggiornamento o la chiusura della pagina. Non viene salvato in modo permanente per la tua sicurezza.",
