    "apikey.howToGetTitle": "Come ottenere una chiave API Gemini",
    "apikey.howToGet1": "Puoi ottenere una chiave API gratuita per accedere ai modelli Gemini in Google AI Studio.",
    "apikey.step1": "<li>Vai a <a href=\"https://aistudio.google.com/app/apikey\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"underline text-[var(--accent-primary)] hover:text-[var(--accent-primary-hover)]\">Google AI Studio</a>.</li>",
    "apikey.step2": "<li>Accedi con il tuo account Google.</li>",
    "apikey.step3": "<li>Nella pagina aperta, fai clic sul pulsante <strong>\"Crea chiave API nel nuovo progetto\"</strong>.</li>",
    "apikey.step4": "<li>Dopo alcuni secondi, la tua chiave verrà generata. Sembrerà una lunga stringa di caratteri casuali.</li>",
    "apikey.step5": "<li>Fai clic sull’icona di copia accanto alla chiave.</li>",
    "apikey.step6": "<li>Torna qui e incolla la chiave copiata nel campo sopra.</li>",
    "apikey.warning2": "<strong>Importante:</strong> conserva la chiave in un luogo sicuro e non condividerla con nessuno. L’editor non salva la chiave in modo permanente e non la trasmette da nessuna parte se non direttamente all’API di Google durante la generazione del codice.",
