    "about.title": "Informazioni sull’editore \"VereTka\".",
    "about.p1": "<strong className=\"text-[var(--text-primary)]\">VereTkа</strong> è un semplice editor vettoriale progettato per la creazione rapida di primitive grafiche e la generazione del codice Python corrispondente per la libreria Tkinter.",
